const REQUIRED_OPTIONS = ['a', 'b', 'c', 'd', 'e'];
const REQUIRED_FLAGS = REQUIRED_OPTIONS.map((option) => `--${option}`);
const REQUIRED_FLAG_SET = new Set(REQUIRED_FLAGS);
const INTEGER_PATTERN = /^[+-]?(?:\d+(?:_\d+)*)$/;

function basename(pathname) {
  if (!pathname) {
    return 'test10.mjs';
  }

  const normalized = pathname.replace(/\\/g, '/');
  const pieces = normalized.split('/');
  return pieces[pieces.length - 1] || 'test10.mjs';
}

function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E`;
}

function helpText(programName) {
  return `${usageLine(programName)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
  --e E
`;
}

function writeStdout(text) {
  process.stdout.write(text);
}

function writeStderr(text) {
  process.stderr.write(text);
}

function exitWithHelp(programName) {
  writeStdout(helpText(programName));
  process.exit(0);
}

function exitWithError(programName, message) {
  writeStderr(`${usageLine(programName)}\n`);
  writeStderr(`${programName}: error: ${message}\n`);
  process.exit(2);
}

function parsePythonIntLiteral(rawValue) {
  if (!INTEGER_PATTERN.test(rawValue)) {
    return null;
  }

  let sign = '';
  let digits = rawValue;
  if (digits.startsWith('+') || digits.startsWith('-')) {
    sign = digits[0] === '-' ? '-' : '';
    digits = digits.slice(1);
  }

  return BigInt(`${sign}${digits.replaceAll('_', '')}`);
}

function looksLikeAnotherOption(token) {
  return token.startsWith('-') && parsePythonIntLiteral(token) === null;
}

export function parseTest10Args(argv = process.argv) {
  const programName = basename(argv[1]);
  const parsedValues = new Map();
  const extras = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      exitWithHelp(programName);
    }

    if (!token.startsWith('-') || token === '--') {
      extras.push(token);
      continue;
    }

    if (!token.startsWith('--')) {
      extras.push(token);
      continue;
    }

    const equalsIndex = token.indexOf('=');
    if (equalsIndex !== -1) {
      const flag = token.slice(0, equalsIndex);
      const rawValue = token.slice(equalsIndex + 1);

      if (!REQUIRED_FLAG_SET.has(flag)) {
        extras.push(token);
        continue;
      }

      const value = parsePythonIntLiteral(rawValue);
      if (value === null) {
        exitWithError(programName, `argument ${flag}: invalid int value: '${rawValue}'`);
      }

      parsedValues.set(flag, value);
      continue;
    }

    if (!REQUIRED_FLAG_SET.has(token)) {
      extras.push(token);
      continue;
    }

    const rawValue = argv[index + 1];
    if (rawValue === undefined || looksLikeAnotherOption(rawValue)) {
      exitWithError(programName, `argument ${token}: expected one argument`);
    }

    const value = parsePythonIntLiteral(rawValue);
    if (value === null) {
      exitWithError(programName, `argument ${token}: invalid int value: '${rawValue}'`);
    }

    parsedValues.set(token, value);
    index += 1;
  }

  const missingFlags = REQUIRED_FLAGS.filter((flag) => !parsedValues.has(flag));
  if (missingFlags.length > 0) {
    exitWithError(programName, `the following arguments are required: ${missingFlags.join(', ')}`);
  }

  if (extras.length > 0) {
    exitWithError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    a: parsedValues.get('--a'),
    b: parsedValues.get('--b'),
    c: parsedValues.get('--c'),
    d: parsedValues.get('--d'),
    e: parsedValues.get('--e'),
  };
}

#!/usr/bin/env node
import {
  CliHelpRequested,
  CliParseError,
  errorText,
  helpText,
  parseArguments,
  programName,
} from "./lib/cli.mjs";
import { nodeConnectivity } from "./lib/connectivity.mjs";
import { pyFloat, toPythonString } from "./lib/format.mjs";
import { Graph } from "./lib/graph.mjs";
import { bfsEdges, dfsEdges, dijkstraPath, dijkstraPathLength } from "./lib/search.mjs";
import { minimumSpanningTree } from "./lib/spanning.mjs";

function printLine(value) {
  process.stdout.write(`${toPythonString(value)}\n`);
}

export function main(argv = process.argv) {
  const prog = programName(argv);
  let args;

  try {
    args = parseArguments(argv.slice(2), prog);
  } catch (error) {
    if (error instanceof CliHelpRequested) {
      process.stdout.write(helpText(prog));
      return 0;
    }

    if (error instanceof CliParseError) {
      process.stderr.write(errorText(prog, error.message));
      return 2;
    }

    throw error;
  }

  const graph = new Graph();
  graph.addWeightedEdgesFrom([
    [args.a, args.b, pyFloat(1)],
    [args.b, args.c, pyFloat(2)],
    [args.c, args.d, pyFloat(3)],
    [args.d, args.e, pyFloat(4)],
    [args.a, args.e, pyFloat(5)],
  ]);

  printLine(graph.numberOfEdges());
  printLine(graph.getEdgeWeight(args.a, args.b));

  const mst = minimumSpanningTree(graph);
  printLine(mst.numberOfEdges());
  printLine(mst.hasEdge(args.a, args.b));
  printLine(dijkstraPathLength(graph, args.a, args.e));
  printLine(dijkstraPath(graph, args.a, args.e));
  printLine(bfsEdges(graph, args.a));
  printLine(dfsEdges(graph, args.a));
  printLine(nodeConnectivity(graph));
  return 0;
}

const exitCode = main(process.argv);
if (exitCode !== 0) {
  process.exit(exitCode);
}

const REQUIRED_OPTIONS = ["a", "b", "c", "d", "e"];
const LONG_OPTIONS = new Set(REQUIRED_OPTIONS.map((name) => `--${name}`));

export class CliHelpRequested extends Error {}

export class CliParseError extends Error {
  constructor(message) {
    super(message);
    this.name = "CliParseError";
  }
}

export function programName(argv = process.argv) {
  const scriptPath = argv[1] ?? "test10.mjs";
  const parts = String(scriptPath).split(/[\\/]/);
  return parts[parts.length - 1] || "test10.mjs";
}

export function helpText(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C --d D --e E

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
  --e E
`;
}

export function errorText(prog, message) {
  return `usage: ${prog} [-h] --a A --b B --c C --d D --e E
${prog}: error: ${message}
`;
}

function isPythonIntLiteral(raw) {
  return /^[+-]?\d(?:_?\d)*$/.test(raw);
}

function parsePythonInt(option, raw) {
  if (!isPythonIntLiteral(raw)) {
    throw new CliParseError(`argument ${option}: invalid int value: '${raw}'`);
  }

  return BigInt(raw.replaceAll("_", ""));
}

function nextTokenLooksLikeOption(token) {
  if (token === undefined) {
    return true;
  }

  if (token.startsWith("--")) {
    return true;
  }

  if (token.startsWith("-") && !isPythonIntLiteral(token)) {
    return true;
  }

  return false;
}

export function parseArguments(argv, prog = programName()) {
  const values = new Map();
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h" || token === "--help") {
      throw new CliHelpRequested();
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const option = equalsIndex === -1 ? token : token.slice(0, equalsIndex);

      if (!LONG_OPTIONS.has(option)) {
        unknown.push(token);
        continue;
      }

      let rawValue;

      if (equalsIndex !== -1) {
        rawValue = token.slice(equalsIndex + 1);
      } else {
        const candidate = argv[index + 1];

        if (nextTokenLooksLikeOption(candidate)) {
          throw new CliParseError(`argument ${option}: expected one argument`);
        }

        rawValue = candidate;
        index += 1;
      }

      values.set(option.slice(2), parsePythonInt(option, rawValue));
      continue;
    }

    unknown.push(token);
  }

  if (unknown.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${unknown.join(" ")}`);
  }

  const missing = REQUIRED_OPTIONS
    .filter((name) => !values.has(name))
    .map((name) => `--${name}`);

  if (missing.length > 0) {
    throw new CliParseError(`the following arguments are required: ${missing.join(", ")}`);
  }

  return {
    a: values.get("a"),
    b: values.get("b"),
    c: values.get("c"),
    d: values.get("d"),
    e: values.get("e"),
    prog,
  };
}

function connectedComponentSize(graph, start) {
  const seen = new Set([start]);
  const queue = [start];

  while (queue.length > 0) {
    const node = queue.shift();

    for (const neighbor of graph.neighbors(node)) {
      if (seen.has(neighbor)) {
        continue;
      }

      seen.add(neighbor);
      queue.push(neighbor);
    }
  }

  return seen.size;
}

function enumerateSimplePaths(graph, source, target) {
  const paths = [];
  const visited = new Set([source]);
  const currentPath = [source];

  function walk(node) {
    if (node === target) {
      paths.push([...currentPath]);
      return;
    }

    for (const neighbor of graph.neighbors(node)) {
      if (neighbor === node || visited.has(neighbor)) {
        continue;
      }

      visited.add(neighbor);
      currentPath.push(neighbor);
      walk(neighbor);
      currentPath.pop();
      visited.delete(neighbor);
    }
  }

  walk(source);
  return paths;
}

function maxInternallyDisjointPathCount(paths) {
  const internalSets = paths.map((path) => path.slice(1, -1));
  let best = 0;

  function search(index, usedNodes, chosenCount) {
    if (chosenCount > best) {
      best = chosenCount;
    }

    for (let current = index; current < internalSets.length; current += 1) {
      const internalNodes = internalSets[current];
      let disjoint = true;

      for (const node of internalNodes) {
        if (usedNodes.has(node)) {
          disjoint = false;
          break;
        }
      }

      if (!disjoint) {
        continue;
      }

      for (const node of internalNodes) {
        usedNodes.add(node);
      }

      search(current + 1, usedNodes, chosenCount + 1);

      for (const node of internalNodes) {
        usedNodes.delete(node);
      }
    }
  }

  search(0, new Set(), 0);
  return best;
}

function localNodeConnectivity(graph, source, target) {
  return maxInternallyDisjointPathCount(enumerateSimplePaths(graph, source, target));
}

export function nodeConnectivity(graph) {
  const nodes = graph.nodes();

  if (nodes.length === 0) {
    return 0;
  }

  if (nodes.length === 1) {
    return graph.degree(nodes[0]);
  }

  if (connectedComponentSize(graph, nodes[0]) !== nodes.length) {
    return 0;
  }

  let best = Infinity;

  for (let leftIndex = 0; leftIndex < nodes.length; leftIndex += 1) {
    for (let rightIndex = leftIndex + 1; rightIndex < nodes.length; rightIndex += 1) {
      const candidate = localNodeConnectivity(graph, nodes[leftIndex], nodes[rightIndex]);
      if (candidate < best) {
        best = candidate;
      }
    }
  }

  return best;
}

function canonicalPair(a, b) {
  if (a <= b) {
    return [a, b];
  }

  return [b, a];
}

function edgeKey(a, b) {
  const [left, right] = canonicalPair(a, b);
  return `${left}::${right}`;
}

export class Graph {
  constructor() {
    this.nodesById = new Map();
    this.edgesById = new Map();
  }

  addNode(node) {
    if (!this.nodesById.has(node)) {
      this.nodesById.set(node, { adjacency: new Map() });
    }
  }

  addNodesFrom(nodes) {
    for (const node of nodes) {
      this.addNode(node);
    }
  }

  addEdge(u, v, weight) {
    this.addNode(u);
    this.addNode(v);

    const key = edgeKey(u, v);
    const existing = this.edgesById.get(key);

    if (existing) {
      existing.weight = weight;
    } else {
      const [left, right] = canonicalPair(u, v);
      this.edgesById.set(key, {
        id: key,
        u: left,
        v: right,
        weight,
        order: this.edgesById.size,
      });
    }

    const sourceAdjacency = this.nodesById.get(u).adjacency;
    if (!sourceAdjacency.has(v)) {
      sourceAdjacency.set(v, key);
    }

    if (u !== v) {
      const targetAdjacency = this.nodesById.get(v).adjacency;
      if (!targetAdjacency.has(u)) {
        targetAdjacency.set(u, key);
      }
    }
  }

  addWeightedEdgesFrom(edges) {
    for (const [u, v, weight] of edges) {
      this.addEdge(u, v, weight);
    }
  }

  nodes() {
    return Array.from(this.nodesById.keys());
  }

  neighbors(node) {
    const record = this.nodesById.get(node);
    if (!record) {
      return [];
    }

    return Array.from(record.adjacency.keys());
  }

  numberOfEdges() {
    return this.edgesById.size;
  }

  hasEdge(u, v) {
    return this.edgesById.has(edgeKey(u, v));
  }

  getEdgeWeight(u, v) {
    const edge = this.edgesById.get(edgeKey(u, v));
    if (!edge) {
      throw new Error(`Missing edge between ${u} and ${v}`);
    }

    return edge.weight;
  }

  edges() {
    return Array.from(this.edgesById.values());
  }

  degree(node) {
    const adjacency = this.nodesById.get(node)?.adjacency;
    if (!adjacency) {
      return 0;
    }

    let degree = 0;
    for (const neighbor of adjacency.keys()) {
      degree += neighbor === node ? 2 : 1;
    }

    return degree;
  }
}

function isReachable(graph, source, target, removedNodes) {
  if (removedNodes.has(source) || removedNodes.has(target)) {
    return false;
  }

  const visited = new Set([source]);
  const queue = [source];
  let index = 0;

  while (index < queue.length) {
    const current = queue[index];
    index += 1;

    if (current === target) {
      return true;
    }

    for (const neighbor of graph.neighbors(current)) {
      if (neighbor === current || removedNodes.has(neighbor) || visited.has(neighbor)) {
        continue;
      }

      visited.add(neighbor);
      queue.push(neighbor);
    }
  }

  return false;
}

function isConnectedIgnoringSelfLoops(graph) {
  const nodes = graph.nodes();
  if (nodes.length === 0) {
    return true;
  }

  const visited = new Set([nodes[0]]);
  const queue = [nodes[0]];
  let index = 0;

  while (index < queue.length) {
    const current = queue[index];
    index += 1;

    for (const neighbor of graph.neighbors(current)) {
      if (neighbor === current || visited.has(neighbor)) {
        continue;
      }

      visited.add(neighbor);
      queue.push(neighbor);
    }
  }

  return visited.size === nodes.length;
}

function visitSubsets(items, subsetSize, visitor, start = 0, chosen = []) {
  if (chosen.length === subsetSize) {
    return visitor(chosen);
  }

  for (let index = start; index <= items.length - (subsetSize - chosen.length); index += 1) {
    chosen.push(items[index]);
    if (visitSubsets(items, subsetSize, visitor, index + 1, chosen)) {
      return true;
    }
    chosen.pop();
  }

  return false;
}

function localNodeConnectivity(graph, source, target) {
  if (!isReachable(graph, source, target, new Set())) {
    return 0;
  }

  const candidates = graph
    .nodes()
    .filter((node) => node !== source && node !== target);

  for (let subsetSize = 0; subsetSize <= candidates.length; subsetSize += 1) {
    const disconnected = visitSubsets(candidates, subsetSize, (chosen) => {
      return !isReachable(graph, source, target, new Set(chosen));
    });

    if (disconnected) {
      return subsetSize;
    }
  }

  return candidates.length;
}

export function nodeConnectivity(graph) {
  const nodes = graph.nodes();
  if (nodes.length === 0) {
    return 0;
  }

  if (!isConnectedIgnoringSelfLoops(graph)) {
    return 0;
  }

  let pivot = nodes[0];
  let bestConnectivity = graph.degree(pivot);

  for (let index = 1; index < nodes.length; index += 1) {
    const node = nodes[index];
    const degree = graph.degree(node);
    if (degree < bestConnectivity) {
      pivot = node;
      bestConnectivity = degree;
    }
  }

  const pivotNeighbors = graph.neighbors(pivot);
  const pivotNeighborSet = new Set(pivotNeighbors);

  for (const node of nodes) {
    if (node === pivot || pivotNeighborSet.has(node)) {
      continue;
    }

    bestConnectivity = Math.min(bestConnectivity, localNodeConnectivity(graph, pivot, node));
  }

  // NetworkX's global routine keeps self-loops in the degree bound and neighbor set.
  for (let leftIndex = 0; leftIndex < pivotNeighbors.length; leftIndex += 1) {
    for (let rightIndex = leftIndex + 1; rightIndex < pivotNeighbors.length; rightIndex += 1) {
      const left = pivotNeighbors[leftIndex];
      const right = pivotNeighbors[rightIndex];

      if (!graph.hasEdge(left, right)) {
        bestConnectivity = Math.min(bestConnectivity, localNodeConnectivity(graph, left, right));
      }
    }
  }

  return bestConnectivity;
}
